// Build yesterday's date range for filter
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
yesterday.setHours(0, 0, 0, 0);
const today = new Date(now);
today.setHours(0, 0, 0, 0);

return [{
  json: {
    yesterday_str: yesterday.toISOString().split('T')[0],
    today_str: today.toISOString().split('T')[0],
    timestamp: now.toISOString(),
    readable_date: now.toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' })
  }
}];

// Gather data from all 3 parallel fetches
const dateInfo    = $('Set — Build Date Range').first().json;
const execData    = $('Airtable — Fetch Yesterday Executions').first().json;
const leadsData   = $('Airtable — Fetch Leads Data').first().json;
const statsData   = $('API — Get Execution Stats').first().json;

const execRecords  = execData?.records  || [];
const leadRecords  = leadsData?.records || [];

// Stats from backend (or demo fallback)
const total        = statsData?.total             ?? execRecords.length;
const successRate  = statsData?.success_rate_pct  ?? statsData?.success_rate ?? 'N/A';
const avgDuration  = statsData?.avg_duration_seconds ?? 'N/A';
const byStatus     = statsData?.by_status         ?? {};

// Count hot leads
const hotLeads = leadRecords.filter(r => {
  const score = (r.fields?.Score || r.fields?.score || r.fields?.Status || '').toLowerCase();
  return score.includes('hot') || score.includes('high');
}).length;

return [{
  json: {
    yesterday_str:  dateInfo.yesterday_str,
    readable_date:  dateInfo.readable_date,
    timestamp:      dateInfo.timestamp,
    // Execution metrics
    exec_count:     execRecords.length,
    total_all_time: total,
    success_rate:   successRate,
    avg_duration:   avgDuration,
    succeeded:      byStatus.success ?? 0,
    failed:         byStatus.error   ?? 0,
    running:        byStatus.running ?? 0,
    // Lead metrics
    new_leads:      leadRecords.length,
    hot_leads:      hotLeads,
    // Raw snippets for Claude
    exec_sample:    JSON.stringify(execRecords.slice(0, 8).map(r => r.fields), null, 2),
    leads_sample:   JSON.stringify(leadRecords.slice(0, 10).map(r => r.fields), null, 2)
  }
}];

